import json, requests

ids = ['1TUP', '2FEJ', '3Q05', '4QO1', '7DHY']
query = '''
query Entries($ids: [String!]!) {
  entries(entry_ids: $ids) {
    rcsb_id
    struct { title }
    rcsb_entry_info {
      resolution_combined
      deposited_polymer_entity_instance_count
      experimental_method
    }
    rcsb_accession_info { initial_release_date }
    polymer_entities {
      rcsb_id
      rcsb_polymer_entity { pdbx_description }
      entity_poly { type rcsb_sample_sequence_length }
      rcsb_polymer_entity_container_identifiers {
        auth_asym_ids
        asym_ids
        reference_sequence_identifiers {
          database_accession
          database_name
        }
      }
      rcsb_polymer_entity_align {
        aligned_regions {
          ref_beg_seq_id
          ref_end_seq_id
          entity_beg_seq_id
          entity_end_seq_id
          length
        }
      }
    }
  }
}
'''
resp = requests.post('https://data.rcsb.org/graphql', json={'query': query, 'variables': {'ids': ids}}, timeout=60)
print('HTTP', resp.status_code)
data = resp.json()
with open('/tmp/p04637_report/rcsb_graphql_selected.json', 'w') as f:
    json.dump(data, f, indent=2)
print(json.dumps(data, indent=2)[:30000])
</execute>

