import json, time, requests

with open('/tmp/p04637_report/rcsb_exact_P04637.json') as f:
    exact = json.load(f)
result = exact.get('result', {})
entity_ids = [x['identifier'] for x in result.get('result_set', [])]
entry_ids = sorted(set(x.split('_')[0] for x in entity_ids))

query = '''
query Entries($ids: [String!]!) {
  entries(entry_ids: $ids) {
    rcsb_id
    struct { title }
    rcsb_entry_info {
      resolution_combined
      deposited_polymer_entity_instance_count
      experimental_method
    }
    rcsb_accession_info { initial_release_date }
    polymer_entities {
      rcsb_id
      rcsb_polymer_entity { pdbx_description }
      entity_poly { type rcsb_sample_sequence_length }
      rcsb_polymer_entity_container_identifiers {
        auth_asym_ids
        asym_ids
        reference_sequence_identifiers {
          database_accession
          database_name
        }
      }
      rcsb_polymer_entity_align {
        aligned_regions {
          ref_beg_seq_id
          entity_beg_seq_id
          length
        }
      }
    }
  }
}
'''

all_entries = []
for start in range(0, len(entry_ids), 50):
    chunk = entry_ids[start:start+50]
    for attempt in range(3):
        try:
            r = requests.post('https://data.rcsb.org/graphql', json={'query': query, 'variables': {'ids': chunk}}, timeout=90)
            r.raise_for_status()
            j = r.json()
            if 'errors' in j:
                raise RuntimeError(j['errors'])
            all_entries.extend(j['data']['entries'])
            break
        except Exception as e:
            if attempt == 2:
                raise
            time.sleep(2 ** attempt)
    print(f'Fetched {min(start+50, len(entry_ids))}/{len(entry_ids)}')

with open('/tmp/p04637_report/rcsb_all_P04637_metadata.json', 'w') as f:
    json.dump(all_entries, f, indent=2)

p53_dna = []
for e in all_entries:
    ents = e.get('polymer_entities') or []
    p53_ents = []
    dna_ents = []
    for ent in ents:
        typ = (ent.get('entity_poly') or {}).get('type', '')
        desc = (ent.get('rcsb_polymer_entity') or {}).get('pdbx_description', '') or ''
        refs = ((ent.get('rcsb_polymer_entity_container_identifiers') or {}).get('reference_sequence_identifiers') or [])
        if any(r.get('database_accession') == 'P04637' for r in refs):
            p53_ents.append(ent)
        if 'polydeoxyribonucleotide' in typ or 'DNA' in desc.upper():
            dna_ents.append(ent)
    if p53_ents and dna_ents:
        res = (e.get('rcsb_entry_info') or {}).get('resolution_combined') or []
        p53_dna.append({
            'pdb_id': e['rcsb_id'],
            'title': (e.get('struct') or {}).get('title'),
            'method': (e.get('rcsb_entry_info') or {}).get('experimental_method'),
            'resolution': min(res) if res else None,
            'release': (e.get('rcsb_accession_info') or {}).get('initial_release_date'),
            'p53_entities': [{
                'entity_id': x['rcsb_id'],
                'description': (x.get('rcsb_polymer_entity') or {}).get('pdbx_description'),
                'chains': (x.get('rcsb_polymer_entity_container_identifiers') or {}).get('auth_asym_ids'),
                'alignment': x.get('rcsb_polymer_entity_align')
            } for x in p53_ents],
            'dna_entities': [{
                'entity_id': x['rcsb_id'],
                'description': (x.get('rcsb_polymer_entity') or {}).get('pdbx_description'),
                'chains': (x.get('rcsb_polymer_entity_container_identifiers') or {}).get('auth_asym_ids')
            } for x in dna_ents]
        })

ranked = sorted(p53_dna, key=lambda x: (x['resolution'] is None, x['resolution'] if x['resolution'] is not None else 999, x['pdb_id']))
with open('/tmp/p04637_report/p53_dna_structures.json', 'w') as f:
    json.dump(ranked, f, indent=2)

print('All metadata entries saved:', len(all_entries))
print('Entries with both P04637 and DNA entities:', len(ranked))
print('\nTop 20 by resolution (X-ray only):')
for x in [z for z in ranked if z['method'] == 'X-ray'][:20]:
    print(f"{x['pdb_id']} | {x['resolution']:.2f} A | {x['p53_entities'][0]['chains']} | {x['title']}")
print('\nNon-X-ray examples:')
for x in ranked:
    if x['method'] != 'X-ray':
        print(f"{x['pdb_id']} | {x['method']} | {x['resolution'] if x['resolution'] is not None else 'NA'} | {x['title']}")
print('\nSaved complete p53+DNA structure table: /tmp/p04637_report/p53_dna_structures.json')
</execute>

