import json, os
from Bio.PDB.MMCIF2Dict import MMCIF2Dict

selected = ['1TUP', '3Q05', '5MCT', '6ZNC', '7B4H', '7B4N']
with open('/tmp/p04637_report/rcsb_all_P04637_metadata.json') as f:
    metadata = {e['rcsb_id']: e for e in json.load(f)}

summary = []
for pdb_id in selected:
    d = MMCIF2Dict(f'/tmp/p04637_report/cif/{pdb_id}.cif')
    entry = metadata[pdb_id]
    scheme = d.get('_pdbx_poly_seq_scheme.auth_asym_id', [])
    seq_ids = d.get('_pdbx_poly_seq_scheme.seq_id', [])
    pdb_seq_nums = d.get('_pdbx_poly_seq_scheme.pdb_seq_num', [])
    ins_codes = d.get('_pdbx_poly_seq_scheme.pdb_ins_code', [])
    scheme_map = {}
    for i, ch in enumerate(scheme):
        scheme_map[(ch, int(seq_ids[i]))] = (int(pdb_seq_nums[i]), ins_codes[i] if i < len(ins_codes) else '?')

    atom_chains = d.get('_atom_site.auth_asym_id', [])
    atom_label_seq = d.get('_atom_site.label_seq_id', [])
    observed = {}
    for ch, sid in zip(atom_chains, atom_label_seq):
        if sid not in ('.', '?'):
            observed.setdefault(ch, set()).add(int(sid))

    chains = []
    for ent in entry.get('polymer_entities') or []:
        ident = ent['rcsb_polymer_entity_container_identifiers']
        refs = ident.get('reference_sequence_identifiers') or []
        if not any(r.get('database_accession') == 'P04637' for r in refs):
            continue
        regs = []
        for block in ent.get('rcsb_polymer_entity_align') or []:
            regs.extend(block.get('aligned_regions') or [])
        e2u = {}
        for r in regs:
            for e in range(r['entity_beg_seq_id'], r['entity_beg_seq_id'] + r['length']):
                e2u[e] = r['ref_beg_seq_id'] + e - r['entity_beg_seq_id']
        for ch in ident.get('auth_asym_ids') or []:
            u2auth = {}
            for sid in observed.get(ch, set()):
                if sid in e2u and (ch, sid) in scheme_map:
                    u2auth[e2u[sid]] = scheme_map[(ch, sid)]
            dbd_auth = {u: v for u, v in u2auth.items() if 102 <= u <= 292}
            def author_for(u):
                v = u2auth.get(u)
                if not v:
                    return None
                return f"{v[0]}{v[1] if v[1] not in ('?', '') else ''}"
            chains.append({
                'chain': ch,
                'uniprot_102_author': author_for(102),
                'uniprot_176_author': author_for(176),
                'uniprot_245_author': author_for(245),
                'uniprot_292_author': author_for(292),
                'observed_dbd_author_min': min((v[0] for v in dbd_auth.values()), default=None),
                'observed_dbd_author_max': max((v[0] for v in dbd_auth.values()), default=None),
                'observed_dbd_count': len(dbd_auth)
            })
    res = (entry.get('rcsb_entry_info') or {}).get('resolution_combined') or []
    summary.append({
        'pdb_id': pdb_id,
        'title': (entry.get('struct') or {}).get('title'),
        'method': (entry.get('rcsb_entry_info') or {}).get('experimental_method'),
        'resolution': min(res) if res else None,
        'chains': chains
    })

with open('/tmp/p04637_report/author_residue_mapping_selected.json', 'w') as f:
    json.dump(summary, f, indent=2)

for e in summary:
    print(f"\n{e['pdb_id']} | {e['method']} | {e['resolution']} A")
    for c in e['chains']:
        print(f"  chain {c['chain']}: UniProt 102 -> PDB {c['uniprot_102_author']}; 176 -> {c['uniprot_176_author']}; 245 -> {c['uniprot_245_author']}; 292 -> {c['uniprot_292_author']}; observed DBD author range {c['observed_dbd_author_min']}-{c['observed_dbd_author_max']} (n={c['observed_dbd_count']})")
print('\nSaved: /tmp/p04637_report/author_residue_mapping_selected.json')
